import { useState } from 'react';
import Markdown from 'react-markdown';
import rehypeRaw from 'rehype-raw';
import rehypeUnwrapImages from 'rehype-unwrap-images';
import remarkGfm from 'remark-gfm';
import DOMPurify from 'dompurify';
import { defaultThumbWidth } from '../shared/constants';
import {
  StyledHeader,
  StyledSubheader,
  StyledSubheader3,
  StyledSubheader4,
  StyledParagraph
} from '../styled';


function firstFieldBlank(table) {
  let element = table;
  while (element) {
    if (element.type && element.type === "comment") {
      return element.value === " ";
    } else if (element.children) {
      element = element.children[0];
    } else {
      return false;
    }
  }
}


function CustomMarkdown({
  children,
  linkClassName='site-link',
  extraClasses='',
  customComponents={},
  openModal=null,
  assetPath='/',
  unhide=false,
}) {
  return (
    <Markdown
      rehypePlugins={[rehypeRaw, rehypeUnwrapImages]}
      remarkPlugins={[remarkGfm]}
      components={{
        a({ href, children, ...props }) {
          return (
            <a className={linkClassName} href={href} {...props}>
              &gt;&gt;{children}&lt;&lt;
            </a>
          );
        },
        blockquote({ children, ...props }) {
          let quotation, speaker;
          if (
            children[1]?.props?.children == "QUOTATION"
          ) {
            quotation = children
              .slice(2, children.length - 2)
              .filter(q => q.type === "p");
            speaker = children[children.length - 2]?.props?.children;
            return (
              <aside className="p-quote-card" {...props}>
                <div className="p-quote">
                  {quotation.map(function (line, i) {
                    return (
                      <StyledParagraph key={line.key}>
                        {line.props.children}
                      </StyledParagraph>
                    );
                  })}
                </div>
                <StyledParagraph>{speaker}</StyledParagraph>
              </aside>
            )
          } else {
            quotation = children.filter(q => q.type === "p");;
            return (
              <aside className="p-quote-card italic">
                {quotation.map(function (line, i) {
                  return (
                    <StyledParagraph key={line.key}>
                      {line.props.children}
                    </StyledParagraph>
                  );
                })}
              </aside>
            );
          }
        },
        img({ ...props }) {
          const { src, alt, title } = props;

          if (alt === 'separator') {
            const svg = require(`../../assets/factions/${src}`)
            return (
              <img src={svg} className="separator" alt="" />
            );
          }

          const image = require(`../../assets${assetPath}/${src}`);
          const [align, widthFactor] = alt.split('-');
          let width = Math.round((defaultThumbWidth * widthFactor) / 10) * 10;
          if (width < 100) { width = 100; }
          if (width > 500) { width = 500; }
          const sanitizedTCaption = () => ({
            __html: DOMPurify.sanitize(title)
          })
          return (
            <div className={`thumb t${align}`}>
              <div className="thumbinner" style={{ width: width + 'px' }}>
                <a className="image" role="button" onClick={() => openModal(image, title)}>
                  <img className="thumbimage" src={image} alt={title} />
                </a>
                <div
                  className="thumbcaption"
                  dangerouslySetInnerHTML={sanitizedTCaption()}
                />
              </div>
            </div>
          );
        },
        h1({ ...props }) {
          return <StyledSubheader className={`spaced-head ${extraClasses}`} {...props} />
        },
        h2({ ...props }) {
          return <StyledSubheader className={extraClasses} {...props} />
        },
        h3({ ...props }) {
          return <StyledSubheader3 className={`spaced-head ${extraClasses}`} {...props} />
        },
        h4({ ...props }) {
          return <StyledSubheader3 className={extraClasses} {...props} />
        },
        h5({ ...props }) {
          return <StyledSubheader3 className={`case-match ${extraClasses}`} {...props} />
        },
        table({ ...props }) {
          if (firstFieldBlank(props.node)) {
            return <table className="objective-table" {...props} />
          }
          return <table className="outcome-table" {...props} />
        },
        ul({ node, ...props }) {
          const galleryboxes = node.children.filter(li => li.tagName === 'li');
          return (
            <ul className="gallery" {...props}>
              {galleryboxes.map(function (item, i) {
                if (!item.children) {
                  return null;
                }

                // only necessary for md with html tags?
                const children = item.children.filter(child => (
                  child.type === 'element')
                );

                const { alt, src, title } = children[0].properties;
                const hide = alt === "hidden" && unhide === false;
                if (hide) {
                  return null;
                }

                const image = require(`../../assets${assetPath}/${src}`);
                const sanitizedGCaption = () => ({
                  __html: DOMPurify.sanitize(title)
                })
                return (
                  <li className="gallerybox" key={`gb-${i}`}>
                    <div className="thumb">
                      <div className="gallery-img-wrapper">
                        <a
                          className="image"
                          role="button"
                          onClick={() => openModal(image, title)}
                        >
                          <img className="thumbimage" src={image} />
                        </a>
                      </div>
                    </div>
                    <div className="gallerytext">
                      <p dangerouslySetInnerHTML={sanitizedGCaption()} />
                    </div>
                  </li>
                )
              })}
            </ul>
          )
        },
        ...customComponents,
      }}
    >
      {children}
    </Markdown>
  );
}

export default CustomMarkdown;