import { useEffect, useState } from 'react';
import { useParams } from 'react-router';
import ImageModal from '../ImageModal';
import CustomMarkdown from '../shared/CustomMarkdown';
import SectionParagraph from '../shared/SectionParagraph';
import allFactions from './factionPageData/index';
import {
  StyledHeader,
  StyledSubheader,
  StyledSubheader3,
} from '../styled';
import './factions.css';

import exterminatus from '../../assets/exterminatus.jpeg';

function FactionDataPage() {
  const [markdownText, setMarkdownText] = useState('');

  const params = useParams()
  const { factionId } = params;

  useEffect(() => {
    import(`./factionPageData/factionMarkdown/campaignDataMarkdown/${factionId}.md`)
      .then(res => {
        fetch(res.default)
          .then(res => res.text())
          .then(res => setMarkdownText(res))
          .catch(err => console.log(err));
      })
      .catch(err => console.log(err));
  }, [factionId]);

  const faction = allFactions[factionId];
  if (!faction) {
    return (
      <article>
        <StyledHeader>All records purged</StyledHeader>
        <img src={exterminatus} alt="" />
      </article>
    );
  }

  const {
    title, subhead, symbol, summary, orkify, campaignId, factionRedirect
  } = faction;

  return (
    <div className="faction-page">
      <section className="faction-header">
        <div className="faction-headers">
          <StyledHeader className={orkify ? "ork-heading" : ""}>{title}</StyledHeader>
          <StyledSubheader className={orkify ? "ork-heading" : ""}>{subhead}</StyledSubheader>
        </div>
      </section>

      <section className="faction-summary mt1">
        <a className={`site-link ${orkify ? 'ork-link' : ''}`} href={`#/factions/${factionRedirect ?? factionId}`}>
          &gt;&gt;VIEW FULL FACTION DESCRIPTION&lt;&lt;
        </a>

        {campaignId && (
          <>
            <StyledSubheader3 className={orkify ? "ork-heading spaced-head" : "spaced-head"}>
              Current Deployment
            </StyledSubheader3>
            <a className={`site-link ${orkify ? 'ork-link' : ''}`} href={`#/campaigns/${campaignId}`}>
              &gt;&gt;VIEW FACTION ENGAGEMENT OVERVIEW&lt;&lt;
            </a>
          </>
        )}

        <CustomMarkdown>
          {markdownText}
        </CustomMarkdown>

        {summary && summary.map(function (paragraph, index) {
          return (
            <SectionParagraph
              key={`paragraph-${index}`}
              paragraph={paragraph}
            />
          );
        })}
      </section>

      <img src={symbol} className="end-symbol" alt="" />
    </div>
  );
}

export default FactionDataPage;