import { useEffect, useState } from 'react';
import { useParams } from 'react-router';
import CustomMarkdown from '../shared/CustomMarkdown';
import ImageModal from '../ImageModal';
import SectionParagraph from '../shared/SectionParagraph';
import allFactions from './factionPageData/index';
import {
  StyledHeader, StyledSubheader,
} from '../styled';
import './factions.css';

import exterminatus from '../../assets/exterminatus.jpeg';

function FactionPage() {
  const [markdownText, setMarkdownText] = useState('');
  const [imageInModal, setImageInModal] = useState(null);

  function closeModal() {
    setImageInModal(null);
  }
  function openModal(src, alt) {
    setImageInModal({ src, alt });
  }

  const params = useParams()
  const { factionId } = params;

  useEffect(() => {
    import(`./factionPageData/factionMarkdown/${factionId}.md`)
      .then(res => {
        fetch(res.default)
          .then(res => res.text())
          .then(res => setMarkdownText(res))
          .catch(err => console.log(err));
      })
      .catch(err => console.log(err));
  }, [factionId]);

  const faction = allFactions[factionId];
  if (!faction) {
    return (
      <article>
        <StyledHeader>All records purged</StyledHeader>
        <img src={exterminatus} alt="" />
      </article>
    );
  }

  const { title, subhead, symbol, headerImg, summary, campaignId, orkify } = faction;
  const unhide = faction.unhide || false;

  return (
    <div className="faction-page">
      {imageInModal ? <ImageModal closeModal={closeModal} image={imageInModal} /> : null}

      <section className="faction-header">
        {headerImg && <div className="faction-main" style={{backgroundImage: `url(${headerImg})`}}></div>}
        <div className="faction-headers">
          <StyledHeader className={orkify ? "ork-heading" : ""}>{title}</StyledHeader>
          <StyledSubheader className={orkify ? "ork-heading" : ""}>{subhead}</StyledSubheader>
        </div>
      </section>

      {campaignId && (
        <section className="faction-summary mb1 mt1">
          <a
            className={`site-link ${orkify ? 'ork-link' : ''}`}
            href={`#/factions/${factionId}/data`}
          >
            &gt;&gt;VIEW CURRENT OPERATIONS REPORT&lt;&lt;
          </a>
        </section>
      )}

      <section className="faction-summary">
        <CustomMarkdown
          openModal={openModal}
          assetPath="/portraits"
          unhide={unhide}
        >
          {markdownText}
        </CustomMarkdown>
      </section>

      <img src={symbol} className="end-symbol" alt="" />
    </div>
  );
}

export default FactionPage;