import { useState } from 'react';
import { NavLink, Routes, Route } from 'react-router-dom';

import Home from './Home';
import Background from './Background';
import Maps from './maps/Maps';
import MapPage from './maps/MapPage';
import Events from './events/Events';
import EventPage from './events/EventPage';
import Factions from './factions/Factions';
import FactionPage from './factions/FactionPage';
import FactionDataPage from './factions/FactionDataPage';
import Characters from './characters/Characters';
import CharacterPage from './characters/CharacterPage';
import Campaigns from './campaigns/Campaigns';
import CampaignPage from './campaigns/CampaignPage';

import '../styles/App.css';
import './shared/shared.css';

function App() {
  const [menuOpen, setMenuOpen] = useState(false);
  function toggleMenuOpen() {
    return setMenuOpen(!menuOpen);
  }
  function closeMenu() {
    return setMenuOpen(false);
  }

  return (
    <div className="App">

      <header className="header">
        <input
          id="side-menu"
          className="side-menu"
          type="checkbox"
          checked={menuOpen}
          onChange={toggleMenuOpen}
        />
        <label className="hamb" htmlFor="side-menu">
          <span className="hamb-line"></span>
        </label>

        <nav className="menu-nav">
          <ul className="font-face-ca navigation">
            <li onClick={closeMenu}>
              <NavLink
                to="/"
                className={({ isActive }) => isActive ? "menu-active" : ""}
              >
                Home
              </NavLink>
            </li>
            <li onClick={closeMenu}>
              <NavLink
                to="/background"
                className={({ isActive }) => isActive ? "menu-active" : ""}
              >
                Background
              </NavLink>
            </li>
            <li onClick={closeMenu}>
              <NavLink
                to="/maps"
                className={({ isActive }) => isActive ? "menu-active" : ""}
              >
                Maps
              </NavLink>
            </li>
            <li onClick={closeMenu}>
              <NavLink
                to="/events"
                className={({ isActive }) => isActive ? "menu-active" : ""}
              >
                Events
              </NavLink>
            </li>
            <li onClick={closeMenu}>
              <NavLink
                to="/factions"
                className={({ isActive }) => isActive ? "menu-active" : ""}
              >
                Factions
              </NavLink>
            </li>
            <li onClick={closeMenu}>
              <NavLink
                to="/characters"
                className={({ isActive }) => isActive ? "menu-active" : ""}
              >
                Characters
              </NavLink>
            </li>
            <li onClick={closeMenu}>
              <NavLink
                to="/campaigns"
                className={({ isActive }) => isActive ? "menu-active" : ""}
              >
                Campaigns
              </NavLink>
            </li>
          </ul>
        </nav>
      </header>

      <Routes>
        <Route path="/" element={
          <>
            <div id="banner-image" className="home"></div>
            <article>
              <Home />
            </article>
          </>
        }>
        </Route>

        <Route path="/background" element={
          <>
            <div id="banner-image" className="background"></div>
            <article>
              <Background />
            </article>
          </>
        }>
        </Route>

        <Route path="/maps" element={
          <>
            <div id="maps-background">
              <Maps />
            </div>
          </>
        }>
        </Route>

        <Route path="/maps/:mapId" element={<MapPage />} />

        <Route path="/events" element={
          <article>
            <Events />
          </article>
        }>
        </Route>

        <Route path="/events/:eventId" element={<EventPage />} />

        <Route path="/factions" element={
          <article>
            <Factions />
          </article>
        }>
        </Route>

        <Route path="/factions/:factionId" element={<FactionPage />} />

        <Route path="/factions/:factionId/data" element={<FactionDataPage />} />

        <Route path="/characters" element={
          <article>
            <Characters />
          </article>
        }>
        </Route>

        <Route path="/characters/:characterId" element={<CharacterPage />} />

        <Route path="/campaigns" element={
          <article>
            <Campaigns />
          </article>
        }>
        </Route>

        <Route path="/campaigns/:campaignId" element={<CampaignPage />} />
      </Routes>
    </div>
  );
}

export default App;
