import { useParams } from 'react-router';
import { useNavigate } from 'react-router-dom';
import './campaigns.css';
import {
  StyledHeader, StyledSubheader, StyledSubheader3
} from '../styled';
import allCampaigns from './campaignPageData/index';

import exterminatus from '../../assets/exterminatus.jpeg';


function EventButton(props) {
  const { id, title, src, date, description, factions } = props.event;
  const navigate = useNavigate();
  function goToEvent(id) {
    if (id) {
      navigate(`/events/${id}`);
    }
  }
  return (
    <section
      className={`event-section ${id ? 'event-record' : ''}`}
      onClick={() => goToEvent(id)}
    >
      <div className="thumb tleft">
        <div className="thumbinner" alt={title}>
          <a className="image">
            <img className="thumbimage" src={src} />
          </a>
        </div>
      </div>

      <article>
        <StyledSubheader>{title}</StyledSubheader>
        <StyledSubheader3>{date}</StyledSubheader3>
        <p>{description}</p>
        <ul className="faction-indicators">
          {factions.map(function(faction, i) {
            return (
              <li key={`fi-${i}`}>
                <img src={faction.symbol} />
              </li>
            )
          })}
        </ul>
      </article>
    </section>
  );
}

function FactionButton(props) {
  const { id, identifier, name, symbol } = props.faction;
  const navigate = useNavigate();
  function goToFaction(id) {
    if (id) {
      navigate(`/factions/${id}/data`);
    }
  }
  return (
    <div className="faction-btn" onClick={() => goToFaction(id)}>
      <section className="faction-half">
        <h2>{name}</h2>
        <h3>{identifier}</h3>
      </section>
      <section className="faction-half">
        <img src={symbol} className="symbol" />
      </section>
    </div>
  );
}

function CampaignPage() {
  const params = useParams()
  const { campaignId } = params;
  const campaign = allCampaigns[campaignId];

  if (!campaign) {
    return (
      <article>
        <StyledHeader>All records purged</StyledHeader>
        <img src={exterminatus} alt="" />
      </article>
    );
  }

  const { id, name, type, start, locations, factions, events } = campaign;
  const locTitle = locations.length === 1 ? "Location" : "Locations";

  return (
    <div className="article-page">
      <h1 className="page-header">
        <span>+++{name}+++</span>
      </h1>

      <aside className="campaign-info-bar">
        <section>
          <h2>Campaign Type</h2>
          <span>{type}</span>
        </section>
        <section>
          <h2>Campaign Start</h2>
          <span>{start}</span>
        </section>
        <section>
          <h2>{locTitle}</h2>
          <ul>
            {locations.map(function (location, i) {
              const { id, name } = location;
              return (
                <li key={`cl-${i}`}>
                  <a className="site-link" href={`#/maps/${id}`}>
                    &gt;&gt;{name}&lt;&lt;
                  </a>
                </li>
              );
            })}
          </ul>
        </section>
      </aside>

      <h1 className="font-face-ca">Factions</h1>
      <ul className="campaign-factions">
        {factions.map(function (faction, i) {
          return (
            <li className="campaign-faction" key={`cf-${i}`}>
              <FactionButton faction={faction} />
            </li>
          )
        })}
      </ul>

      <h1 className="font-face-ca">Events</h1>
      <ul className="campaign-events">
        {events.map(function (event, i) {
          return (
            <li className="campaign-event" key={`ce-${i}`}>
              <EventButton event={event} />
            </li>
          )
        })}
      </ul>
    </div>
  );
}

export default CampaignPage;