import { useEffect, useState } from 'react';
import { useParams } from 'react-router';
import Markdown from 'react-markdown';
import rehypeRaw from 'rehype-raw';
import rehypeUnwrapImages from 'rehype-unwrap-images';
import DOMPurify from 'dompurify';

import ImageModal from '../ImageModal';
import CustomMarkdown from '../shared/CustomMarkdown';
import allMaps from './mapPageData/index';
import { StyledHeader, StyledSubheader, StyledSubheader3 } from '../styled';
import './maps.css';

import exterminatus from '../../assets/exterminatus.jpeg';


function MapPage() {
  const [markdownText, setMarkdownText] = useState('');
  const [imageInModal, setImageInModal] = useState(null);

  const params = useParams();
  const { mapId } = params;

  useEffect(() => {
    import(`./mapPageData/mapMarkdown/${mapId}.md`)
      .then(res => {
        fetch(res.default)
          .then(res => res.text())
          .then(res => setMarkdownText(res))
          .catch(err => console.log(err));
      })
      .catch(err => console.log(err));
  }, [mapId]);

  const map = allMaps[mapId];
  if (!map) {
    return (
      <article>
        <StyledHeader>All records purged</StyledHeader>
        <img src={exterminatus} alt="" />
      </article>
    );
  }

  const {
    category, name, type, presence, portrait,
  } = map;
  let planets, affiliation, system, climate, pop;
  const isPlanet = category === 'planet';
  const isSystem = category === 'system';
  const isStructure = category === 'structure';
  if (isPlanet) {
    ({ affiliation, system, climate, pop } = map);
  } else if (isSystem) {
    ({ affiliation, planets } = map);
  } else if (isStructure) {
    ({ system } = map);
  }

  function closeModal() {
    setImageInModal(null);
  }
  function openModal(src, alt) {
    setImageInModal({ src, alt });
  }

  return (
    <div className="article-page">
      {imageInModal ? <ImageModal closeModal={closeModal} image={imageInModal} /> : null}

      <h1 className="page-header">
        <span>+++{name}+++</span>
      </h1>

      <section className="char-content">
        <aside role="region" className="infobox small">
          {portrait && <a className="image" role="button">
            <img
              className="infobox-image"
              src={portrait}
              alt={name}
              onClick={() => openModal(portrait, name)}
            />
          </a>}

          {system && <div className="infobox-data">
            <h3 className={`infobox-data-label`}>System</h3>
            <div className="infobox-data-value">
              <a className="site-link" href={`#/maps/${system.id}`}>
                &gt;&gt;{system.name}&lt;&lt;
              </a>
            </div>
          </div>}

          <div className="infobox-data">
            <h3 className={`infobox-data-label`}>Type</h3>
            <div className="infobox-data-value">
              <span>{type}</span>
            </div>
          </div>

          {planets && <div className="infobox-data">
            <h3 className="infobox-data-label">Planets</h3>
            <div className="infobox-data-value">
              {planets.map(function (planet, i) {
                return (
                  <>
                    {i !== 0 && <br />}
                    <a
                      className="site-link"
                      href={`#/maps/${planet.id}`}
                    >
                      &gt;&gt;{planet.name}&lt;&lt;
                    </a>
                  </>
                )
              })}
            </div>
          </div>}

          {affiliation && <div className="infobox-data">
            <h3 className="infobox-data-label">Affiliation</h3>
            <div className="infobox-data-value">
              <span>{affiliation}</span>
            </div>
          </div>}

          {climate && <div className="infobox-data">
            <h3 className="infobox-data-label">Climate</h3>
            <div className="infobox-data-value">
              <span>{climate}</span>
            </div>
          </div>}

          {pop && <div className="infobox-data">
            <h3 className="infobox-data-label">Population</h3>
            <div className="infobox-data-value">
              <span>{pop}</span>
            </div>
          </div>}

          {presence && <div className="infobox-data">
            <h3 className="infobox-data-label">Presence</h3>
            <div className="infobox-data-value">
              {presence.map(function (faction, i) {
                return (
                  <>
                    {i !== 0 && <br />}
                    {
                      faction.id
                        ? <a
                            className="site-link"
                            href={`#/factions/${faction.id}`}
                          >
                            &gt;&gt;{faction.name}&lt;&lt;
                          </a>
                        : <span>{faction.name}</span>
                    }
                  </>
                )
              })}
            </div>
          </div>}
        </aside>

        <CustomMarkdown openModal={openModal} closeModal={closeModal}>
          {markdownText}
        </CustomMarkdown>
      </section>
    </div>
  );
}

export default MapPage;