function Planet(props) {
  const {
    id, name, type, affiliation, presence, portrait,
  } = props.planet;
  const factions = presence.map(p => p.name).join(', ')
  return (
    <section className="planet-section">
      <StyledSubheader>
        <a className="site-link" href={`#/maps/${id}`}>
          {name}
        </a>
      </StyledSubheader>
      <img src={portrait} alt={name}></img>
      <StyledSubheader3>{type}</StyledSubheader3>
      <StyledSubheader4>{affiliation}</StyledSubheader4>
    </section>
  );
}

function System(props) {
  const { id, name, planets } = props.system;
  return (
    <section className="system-section">
      <StyledHeader>
        <a className="site-link" href={`#/maps/${id}`}>
          {name}
        </a>
      </StyledHeader>
      <ul>
        {planets.map(function (planet, index) {
          return (
            <li key={`planet-${index}`}>
              <Planet planet={planet} system={name} />
            </li>
          );
        })}
      </ul>
    </section>
  );
}

