import { useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import DOMPurify from 'dompurify';

import { activeCampaigns, pastCampaigns } from './campaignData';
import {
  StyledHeader, StyledSubheader, StyledSubheader3
} from '../styled';
import './campaigns.css';


function Campaign(props) {
  const { id, name, image, type, brief, factions } = props.campaign;
  const navigate = useNavigate();
  function goToFaction(id) {
    if (id) {
      navigate(`/campaigns/${id}`);
    }
  }
  const sanitizedText = () => ({
    __html: DOMPurify.sanitize(brief)
  })
  return (
    <section
      className="campaign-section"
      onClick={() => goToFaction(id)}
    >
      <aside>
        <img src={image} alt={name}></img>
      </aside>
      <article>
        <StyledSubheader>{name}</StyledSubheader>
        <StyledSubheader3>{type}</StyledSubheader3>
        <p dangerouslySetInnerHTML={sanitizedText()} />
        <ul className="faction-indicators">
          {factions.map(function (faction, i) {
            return (
              <li key={`fi-${i}`}>
                <img src={faction.symbol} />
              </li>
            )
          })}
        </ul>
      </article>
    </section>
  );
}

function Campaigns() {
  const activeRef = useRef(null);
  const pastRef = useRef(null);
  const barHeight = '50px';
  function scrollRefWithOffset(scrollRef) {
    scrollRef.current.style.scrollMargin = barHeight;
    scrollRef.current.scrollIntoView({ behavior: 'smooth' });
  }
  return (
    <>
      <nav className="sub-nav">
        <ul className="navigation">
          <li onClick={() => scrollRefWithOffset(activeRef)}>Active Campaigns</li>
          <li onClick={() => scrollRefWithOffset(pastRef)}>Past Campaigns</li>
        </ul>
      </nav>
      <StyledHeader>Campaigns</StyledHeader>
      <StyledSubheader style={{ paddingTop: '1rem' }} ref={activeRef}>Active Campaigns</StyledSubheader>
      <ul className="campaigns-ul">
        {activeCampaigns.map(function (campaign, index) {
          return (
            <li key={`camp-active-${index}`} className="campaign-li">
              <Campaign campaign={campaign} />
            </li>
          );
        })}
      </ul>
      <StyledSubheader style={{ paddingTop: '1rem' }} ref={pastRef}>Past Campaigns</StyledSubheader>
      <ul className="campaigns-ul">
        {pastCampaigns.map(function (campaign, index) {
          return (
            <li key={`camp-past-${index}`} className="campaign-li">
              <Campaign campaign={campaign} />
            </li>
          );
        })}
      </ul>
    </>
  );
}

export default Campaigns;