import { useEffect, useState } from 'react';
import { useParams } from 'react-router';
import DOMPurify from 'dompurify';
import ImageModal from '../ImageModal';
import CustomMarkdown from '../shared/CustomMarkdown';
import allEvents from './eventPageData/index';
import {
  StyledHeader,
  StyledSubheader,
  StyledSubheader3,
  StyledSubheader4,
  StyledParagraph
} from '../styled';
import './events.css';

import exterminatus from '../../assets/exterminatus.jpeg';

function EventPage() {
  const [markdownText, setMarkdownText] = useState('');
  const [imageInModal, setImageInModal] = useState(null);

  function closeModal() {
    setImageInModal(null);
  }
  function openModal(src, alt) {
    setImageInModal({src, alt});
  }

  const params = useParams();
  const { eventId } = params;

  useEffect(() => {
    import(`./eventPageData/eventMarkdown/${eventId}.md`)
      .then(res => {
        fetch(res.default)
          .then(res => res.text())
          .then(res => setMarkdownText(res))
          .catch(err => console.log(err));
      })
      .catch(err => console.log(err));
  }, [eventId]);

  const event = allEvents[eventId];
  if (!event) {
    return (
      <article>
        <StyledHeader>All records purged</StyledHeader>
        <img src={exterminatus} alt="" />
      </article>
    );
  }

  const sanitizedText = (text) => ({
    __html: DOMPurify.sanitize(text)
  })

  const {
    title, date, attacker, defender, gameType, gameDetails, titleCard,
    locationId, location, campaignId,
  } = event;

  return (
    <article className="event-header">
      {imageInModal ? <ImageModal closeModal={closeModal} image={imageInModal} /> : null}

      <div className="event-header">
        <StyledHeader>{title}</StyledHeader>
        <StyledSubheader3>{attacker.faction} vs. {defender.faction}, {date}</StyledSubheader3>
        {gameType && <StyledSubheader4>{gameType}</StyledSubheader4>}
        {gameDetails && gameDetails.map(detail => <StyledSubheader4>{detail}</StyledSubheader4>)}
        {locationId && <StyledSubheader4>
          <a className="site-link" href={`#/maps/${locationId}`}>
            &gt;&gt;{location}&lt;&lt;
          </a>
        </StyledSubheader4>}
        {campaignId && <StyledSubheader4>
          <a className="site-link" href={`#/campaigns/${campaignId}`}>
            &gt;&gt;VIEW FULL CAMPAIGN&lt;&lt;
          </a>
        </StyledSubheader4>}
        <div className="thumb tnone">
          <div className="thumbinner" alt={title}>
            <a className="image" role="button" onClick={() => openModal(titleCard, title)}>
              <img className="thumbimage event-main" src={titleCard} alt={title} />
            </a>
          </div>
        </div>

        <section className="army-lists">
          <aside className="army-list attacker">
            {
              attacker.factionId
                ? <StyledSubheader>
                  <a className="site-link" href={`#/factions/${attacker.factionId}`}>
                    {attacker.faction}
                  </a>
                </StyledSubheader>
                : <StyledSubheader>{attacker.faction}</StyledSubheader>
            }
            {
              attacker.generalId
                ? <StyledSubheader3>
                  <a className="site-link" href={`#/characters/${attacker.generalId}`}>
                    {attacker.general}
                  </a>
                </StyledSubheader3>
                : <StyledSubheader3>{attacker.general}</StyledSubheader3>
            }
            {attacker.detachment && <StyledSubheader4>{attacker.detachment}</StyledSubheader4>}
            {attacker.picture &&
              <div className="thumb tnone">
                <div className="thumbinner" alt={attacker.general}>
                  <a
                    className="image"
                    role="button"
                    onClick={() => openModal(attacker.picture, attacker.general)}
                  >
                    <img className="thumbimage event-faction" src={attacker.picture} />
                  </a>
                </div>
              </div>
            }
            {attacker.armyList?.map(function(unit, i) {
              return <StyledParagraph dangerouslySetInnerHTML={sanitizedText(unit)} key={`unit-${i}`}/>
            })}
          </aside>
          <aside className="army-list defender">
            {
              defender.factionId
                ? <StyledSubheader>
                  <a className="site-link" href={`#/factions/${defender.factionId}`}>
                    {defender.faction}
                  </a>
                </StyledSubheader>
                : <StyledSubheader>{defender.faction}</StyledSubheader>
            }
            {
              defender.generalId
                ? <StyledSubheader3>
                  <a className="site-link" href={`#/characters/${defender.generalId}`}>
                    {defender.general}
                  </a>
                </StyledSubheader3>
                : <StyledSubheader3>{defender.general}</StyledSubheader3>
            }
            {defender.detachment && <StyledSubheader4>{defender.detachment}</StyledSubheader4>}
            {defender.picture &&
              <div className="thumb tnone">
                <div className="thumbinner" alt={defender.general}>
                  <a
                    className="image"
                    role="button"
                    onClick={() => openModal(defender.picture, defender.general)}
                  >
                    <img className="thumbimage event-faction" src={defender.picture} />
                  </a>
                </div>
              </div>
            }
            {defender.armyList?.map(function(unit, i) {
              return <StyledParagraph dangerouslySetInnerHTML={sanitizedText(unit)} key={`unit-${i}`} />
            })}
          </aside>
        </section>
      </div>

      <section className="event-summary">
        <CustomMarkdown openModal={openModal} assetPath="/events">
          {markdownText}
        </CustomMarkdown>
      </section>
    </article>
  );
}

export default EventPage;